                // same fragment as the D3 wrong-tree warning so the two cannot drift.
                println!(
                    "drovr: ENTER IT — {} — drovr cannot move you; `cd` does not persist.",
                    worktree::enter_instruction(&p)
                );
                (p.clone(), Some(p), Some(branch))
            }
            Err(e) => return Err(io::Error::new(e.kind(), format!("drovr: {e}"))),
        }
    } else {
        (project_dir, None, None)
    };

    let task_str = task.unwrap_or_else(|| "(no task specified)".to_string());

    let (workspace, root_pane) = match create_run_workspace(herdr, name, &project_dir) {
        Some(ws) => (Some(ws.id), Some(ws.root_pane)),
        None => (None, None),
    };

    let run = RunState {
        name: name.to_owned(),
        task: task_str,
        agent: Some(agent),
        project_dir,
        phases: vec![
            run::Phase::new("brainstorm"),
            run::Phase::new("plan"),
            run::Phase::new("implement"),
            run::Phase::new("review"),
        ],
        review_phases: vec![],
        gate: "spec".into(),
        cursor: 0,
        workspace,
        root_pane,
        worktree_path,
        worktree_branch,
        archived: false,
        retired_panes: vec![],
        loaded_identity: None,
    };

    // `create_in`, not `save_run`: this is a first write, and the difference
    // between the two is whether `drovr new <existing>` overwrites a live run.
    match run.create_in(&run_dir(name)) {
        Ok(()) => Ok(run),
        Err(e) => Err(reclaim_unrecorded_run(herdr, &run, e)),
    }
}

